#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

bool increasingTriplet(int* nums, int numsSize) {
    int first = 0, second = 0;
    bool hasFirst = false, hasSecond = false;
    for (int i = 0; i < numsSize; ++i) {
        int x = nums[i];
        if (!hasFirst || x <= first) {
            first = x;
            hasFirst = true;
        } else if (!hasSecond || x <= second) {
            second = x;
            hasSecond = true;
        } else {
            return true;
        }
    }
    return false;
}

