public class Main {
    static int[] parseArray(String line) {
        String s = line.trim();
        int l = s.indexOf('['), r = s.lastIndexOf(']');
        s = s.substring(l + 1, r).trim();
        if (s.startsWith("[")) s = s.substring(1, s.length() - 1).trim();
        if (s.isEmpty()) return new int[0];
        String[] parts = s.split(",");
        int[] a = new int[parts.length];
        for (int i = 0; i < parts.length; i++) a[i] = Integer.parseInt(parts[i].trim());
        return a;
    }
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int[] nums = parseArray(br.readLine());
        System.out.println(new Solution().increasingTriplet(nums));
    }
}

